-- Simple PHP IPAM database dump
-- Generated: 2026-04-05 12:00:00
-- Sample dataset v1.11 — for testing only
-- Users: admin/changeme (admin), demo/demo (readonly)
-- API key: sample_api_key_ipam_demo_2026

PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;

-- Table: address_history
CREATE TABLE address_history (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  address_id  INTEGER,
  subnet_id   INTEGER NOT NULL,
  ip          TEXT NOT NULL,
  action      TEXT NOT NULL,
  user_id     INTEGER,
  username    TEXT,
  client_ip   TEXT,
  user_agent  TEXT,
  before_json TEXT,
  after_json  TEXT
);

-- Table: addresses
CREATE TABLE addresses (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  subnet_id  INTEGER NOT NULL,
  ip         TEXT NOT NULL,
  ip_bin     BLOB NOT NULL,
  hostname   TEXT NOT NULL DEFAULT '',
  owner      TEXT NOT NULL DEFAULT '',
  note       TEXT NOT NULL DEFAULT '',
  grp        TEXT NOT NULL DEFAULT '',
  status     TEXT NOT NULL DEFAULT 'used',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(subnet_id, ip),
  FOREIGN KEY(subnet_id) REFERENCES subnets(id) ON DELETE CASCADE
);
CREATE TRIGGER addresses_updated_at
AFTER UPDATE ON addresses FOR EACH ROW
BEGIN
  UPDATE addresses SET updated_at = datetime('now') WHERE id = OLD.id;
END;

-- Table: api_keys
CREATE TABLE api_keys (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  name         TEXT NOT NULL,
  key_hash     TEXT NOT NULL UNIQUE,
  created_at   TEXT NOT NULL DEFAULT (datetime('now')),
  last_used_at TEXT,
  is_active    INTEGER NOT NULL DEFAULT 1,
  created_by   TEXT NOT NULL DEFAULT ''
);

-- Table: audit_log
CREATE TABLE audit_log (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  user_id     INTEGER,
  username    TEXT,
  action      TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id   INTEGER,
  ip          TEXT,
  user_agent  TEXT,
  details     TEXT
);
CREATE TRIGGER audit_log_no_delete
BEFORE DELETE ON audit_log
BEGIN
  SELECT RAISE(ABORT, 'audit_log is append-only');
END;
CREATE TRIGGER audit_log_no_update
BEFORE UPDATE ON audit_log
BEGIN
  SELECT RAISE(ABORT, 'audit_log is append-only');
END;

-- Table: login_attempts
CREATE TABLE login_attempts (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  ip           TEXT NOT NULL,
  attempted_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Table: schema_migrations
CREATE TABLE schema_migrations (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  version    TEXT NOT NULL UNIQUE,
  applied_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Table: sites
CREATE TABLE sites (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  name        TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Table: subnets
CREATE TABLE subnets (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  cidr        TEXT NOT NULL UNIQUE,
  ip_version  INTEGER NOT NULL,
  network     TEXT NOT NULL,
  network_bin BLOB NOT NULL,
  prefix      INTEGER NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  site_id     INTEGER,
  vlan_id     INTEGER,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TRIGGER subnets_updated_at
AFTER UPDATE ON subnets FOR EACH ROW
BEGIN
  UPDATE subnets SET updated_at = datetime('now') WHERE id = OLD.id;
END;

-- Table: users
CREATE TABLE users (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  username      TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'admin',
  is_active     INTEGER NOT NULL DEFAULT 1,
  name          TEXT NOT NULL DEFAULT '',
  email         TEXT NOT NULL DEFAULT '',
  oidc_sub             TEXT,
  last_login_at        TEXT,
  password_changed_at  TEXT,
  theme         TEXT NOT NULL DEFAULT 'auto',
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TRIGGER users_updated_at
AFTER UPDATE ON users FOR EACH ROW
BEGIN
  UPDATE users SET updated_at = datetime('now') WHERE id = OLD.id;
END;

-- Indexes
CREATE INDEX idx_address_history_address_id ON address_history(address_id);
CREATE INDEX idx_address_history_subnet_id ON address_history(subnet_id);
CREATE INDEX idx_addresses_grp ON addresses(grp);
CREATE INDEX idx_addresses_hostname ON addresses(hostname);
CREATE INDEX idx_addresses_owner ON addresses(owner);
CREATE INDEX idx_addresses_status ON addresses(status);
CREATE INDEX idx_addresses_subnet_ipbin ON addresses(subnet_id, ip_bin);
CREATE INDEX idx_login_attempts_ip_time ON login_attempts(ip, attempted_at);
CREATE INDEX idx_subnets_site_id ON subnets(site_id);
CREATE INDEX idx_subnets_ver_prefix_netbin ON subnets(ip_version, prefix, network_bin);
CREATE UNIQUE INDEX idx_users_oidc_sub
  ON users(oidc_sub) WHERE oidc_sub IS NOT NULL;

COMMIT;
PRAGMA foreign_keys=ON;
